sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float hue;
uniform float saturation;
uniform float vibrance;
uniform float lightness;
uniform float style;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = unpremul(image.eval(coord));
    float3 k = float3(0.57735);
    float a = radians(hue);
    float3 v = float3(c.rgb);
    if (style > 1.5) {
        float y = dot(v, float3(0.299, 0.587, 0.114));
        float2 uv = float2(dot(v, float3(-0.14713, -0.28886, 0.436)), dot(v, float3(0.615, -0.51499, -0.10001)));
        uv = float2(uv.x * cos(a) - uv.y * sin(a), uv.x * sin(a) + uv.y * cos(a));
        v = float3(y + 1.13983 * uv.y, y - 0.39465 * uv.x - 0.5806 * uv.y, y + 2.03211 * uv.x);
    } else {
        v = v * cos(a) + cross(k, v) * sin(a) + k * dot(k, v) * (1 - cos(a));
    }
    half3 rgb = half3(v);
    if (style > 0.5) {
        float3 f = float3(rgb);
        float y = dot(f, float3(0.299, 0.587, 0.114));
        float2 uv = float2(dot(f, float3(-0.14713, -0.28886, 0.436)), dot(f, float3(0.615, -0.51499, -0.10001)));
        float uvChroma = length(uv);
        float vibGain = 1.0 + vibrance * max(1.0 - 2.52 * uvChroma, 0.0);
        f = float3(y) + (f - float3(y)) * saturation * vibGain;
        return half4(half3(saturate(f + lightness)) * c.a, c.a);
    }
    rgb = mix(half3(luma(rgb)), rgb, half(saturation));
    half chromaNow = max(rgb.r, max(rgb.g, rgb.b)) - min(rgb.r, min(rgb.g, rgb.b));
    rgb = mix(half3(luma(rgb)), rgb, half(1.0 + vibrance * (1.0 - saturate(chromaNow)))) + half(lightness);
    return half4(saturate(rgb) * c.a, c.a);
}
